import React, { useState, useEffect } from 'react';
import { Database } from '@/integrations/supabase/types';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Edit, Calendar, User, Flag, Tag, Trash2, Loader2 } from 'lucide-react';
import TaskComments from './TaskComments';
import { EditTaskDialog } from './EditTaskDialog';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';
import { useDeleteTask } from '@/hooks/useTaskMutations';
import { useTask } from '@/hooks/useTaskQueries';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

type Profile = Database['public']['Tables']['profiles']['Row'];
type Comment = Database['public']['Tables']['comments']['Row'] & {
  profiles?: Profile;
};

type Task = Database['public']['Tables']['tasks']['Row'] & {
  assigned_profile?: Profile;
  tags?: string[];
  comments?: Comment[];
};

interface TaskDetailDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  task: Task | null;
  projectId: string;
  onTaskDeleted?: () => void;
}

const TaskDetailDialog = ({
  open,
  onOpenChange,
  task,
  projectId,
  onTaskDeleted
}: TaskDetailDialogProps) => {
  const [isEditOpen, setIsEditOpen] = useState(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const deleteTask = useDeleteTask();
  
  // Usar o hook useTask apenas quando o diálogo estiver aberto
  const { data: currentTask, isLoading, isError } = useTask(open ? task?.id : undefined);

  useEffect(() => {
    console.log('[TaskDetailDialog] taskId recebido:', task?.id);
  }, [task?.id]);

  const handleDeleteTask = async () => {
    if (!task?.id) {
      console.error('[TaskDetail] ID da tarefa não encontrado');
      toast.error('Erro ao excluir tarefa: ID não encontrado');
      return;
    }
    
    try {
      console.log('[TaskDetail] Iniciando exclusão da tarefa:', task.id);
      // Fechar o diálogo de confirmação
      setIsDeleteDialogOpen(false);
      // Executar a exclusão
      await deleteTask.mutateAsync(task.id);
      // Notificar sobre a exclusão
      if (onTaskDeleted) onTaskDeleted();
      // Fechar o diálogo principal após a exclusão
      onOpenChange(false);
      console.log('[TaskDetail] Tarefa excluída com sucesso');
    } catch (error: any) {
      console.error('[TaskDetail] Erro ao excluir tarefa:', error);
      toast.error('Erro ao excluir tarefa. Tente novamente.');
    }
  };

  // Se a tarefa foi excluída, fechar o diálogo automaticamente
  useEffect(() => {
    if (!currentTask && !isLoading && open) {
      onOpenChange(false);
    }
  }, [currentTask, isLoading, open, onOpenChange]);

  if (isLoading) {
    return (
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="sr-only">Carregando tarefa</DialogTitle>
            <DialogDescription className="sr-only">Aguarde enquanto os dados da tarefa são carregados.</DialogDescription>
          </DialogHeader>
          <div className="flex items-center justify-center h-40">
            <Loader2 className="mr-2 h-6 w-6 animate-spin" />
            Carregando tarefa...
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  if (isError || !currentTask) {
    return (
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="sr-only">Erro ao carregar tarefa</DialogTitle>
            <DialogDescription className="sr-only">Não foi possível carregar os dados da tarefa.</DialogDescription>
          </DialogHeader>
          <div className="flex items-center justify-center h-40 text-red-500">
            Erro ao carregar tarefa ou tarefa não encontrada.
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high':
        return 'destructive';
      case 'medium':
        return 'default';
      case 'low':
        return 'secondary';
      default:
        return 'outline';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'done':
        return 'bg-green-500';
      case 'doing':
        return 'bg-blue-500';
      case 'todo':
        return 'bg-gray-500';
      default:
        return 'bg-gray-500';
    }
  };

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Detalhes da Tarefa</DialogTitle>
            <DialogDescription className="sr-only">
              Visualize e gerencie os detalhes desta tarefa.
            </DialogDescription>
          </DialogHeader>
          <div className="flex items-center justify-between">
            <DialogTitle className="text-xl">{currentTask?.title}</DialogTitle>
            <div className="flex items-center space-x-2">
              <Button 
                variant="outline" 
                size="sm" 
                onClick={() => setIsEditOpen(true)}
                disabled={!currentTask?.id}
              >
                <Edit className="mr-2 h-4 w-4" />
                Editar
              </Button>
              <Button 
                variant="destructive" 
                size="sm" 
                onClick={() => setIsDeleteDialogOpen(true)}
                disabled={!currentTask?.id || deleteTask.isPending}
              >
                {deleteTask.isPending ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <Trash2 className="mr-2 h-4 w-4" />
                )}
                Excluir
              </Button>
            </div>
          </div>
          <div className="space-y-6 max-h-[70vh] min-h-[300px] overflow-y-auto pr-2">
            <div className="flex items-center space-x-4">
              <div className={`w-3 h-3 rounded-full ${getStatusColor(currentTask?.status || '')}`}></div>
              <Badge variant={getPriorityColor(currentTask?.priority || '')}>
                <Flag className="mr-1 h-3 w-3" />
                {currentTask?.priority}
              </Badge>
            </div>
            <div>
              <h4 className="font-medium mb-2">Descrição</h4>
              <p className="text-slate-50 break-words break-all whitespace-pre-line max-h-32 overflow-y-auto">
                {currentTask?.description || 'Nenhuma descrição fornecida'}
              </p>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {currentTask?.assigned_profile && (
                <div className="flex items-center space-x-2">
                  <User className="h-4 w-4 text-gray-500" />
                  <span>{currentTask.assigned_profile.name}</span>
                </div>
              )}
              {currentTask?.due_date && (
                <div className="flex items-center space-x-2">
                  <Calendar className="h-4 w-4 text-gray-500" />
                  <span>{new Date(currentTask.due_date).toLocaleDateString('pt-BR')}</span>
                </div>
              )}
            </div>
            {currentTask?.tags && currentTask.tags.length > 0 && (
              <div>
                <h4 className="font-medium mb-2 flex items-center">
                  <Tag className="mr-2 h-4 w-4" />
                  Tags
                </h4>
                <div className="flex flex-wrap gap-2">
                  {currentTask.tags.map((tag, index) => (
                    <Badge key={index} variant="outline">
                      {tag}
                    </Badge>
                  ))}
                </div>
              </div>
            )}
            <TaskComments taskId={currentTask?.id} projectId={projectId} comments={currentTask?.comments || []} />
          </div>
        </DialogContent>
      </Dialog>

      <EditTaskDialog 
        open={isEditOpen}
        onOpenChange={setIsEditOpen}
        task={currentTask}
        projectId={projectId}
      />

      <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Confirmar exclusão</AlertDialogTitle>
            <AlertDialogDescription>
              Tem certeza que deseja excluir esta tarefa? Esta ação não pode ser desfeita.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteTask}>
              {deleteTask.isPending ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <Trash2 className="mr-2 h-4 w-4" />
              )}
              Excluir
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

export default TaskDetailDialog;