export function useCreateComment() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async (commentData: Partial<Database['public']['Tables']['comments']['Insert']>) => {
      if (!commentData.task_id) {
        throw new Error('Task ID is required');
      }

      // Verificar sessão antes de prosseguir
      const { data: sessionData } = await supabase.auth.getSession();
      if (!sessionData.session) {
        // Tentar renovar a sessão
        const { error: refreshError } = await supabase.auth.refreshSession();
        if (refreshError) {
          throw new Error('Sessão expirada. Por favor, faça login novamente.');
        }
      }

      // Se não tiver project_id, busca do task
      if (!commentData.project_id) {
        try {
          const { data: task, error } = await supabase
            .from('tasks')
            .select('project_id')
            .eq('id', commentData.task_id)
            .single();

          if (error) throw error;

          if (task?.project_id) {
            commentData.project_id = task.project_id;
          } else {
            throw new Error('Could not determine project ID');
          }
        } catch (error) {
          console.error('Erro ao buscar project_id da task:', error);
          throw new Error('Erro ao buscar informações da tarefa. Verifique sua conexão.');
        }
      }

      // Validações
      if (!commentData.content) {
        throw new Error('Comment content is required');
      }

      if (!commentData.created_by && user) {
        commentData.created_by = user.id;
      }

      if (!commentData.created_by) {
        throw new Error('User ID is required');
      }

      if (!commentData.project_id) {
        throw new Error('Project ID is required');
      }

      // Adiciona timestamp
      const now = new Date().toISOString();
      const comment = {
        ...commentData,
        created_at: now,
        updated_at: now,
      } as Database['public']['Tables']['comments']['Insert'];

      // Log para debug
      console.log('Criando comentário com dados:', comment);
      console.log('Tipos dos campos:', {
        task_id: typeof comment.task_id,
        project_id: typeof comment.project_id,
        content: typeof comment.content,
        created_by: typeof comment.created_by
      });

      try {
        const result = await addComment(comment);
        return result;
      } catch (error) {
        console.error('Erro ao adicionar comentário:', error);
        throw error;
      }
    },
    onSuccess: (_, variables) => {
      // Invalidar queries relacionadas
      queryClient.invalidateQueries({ queryKey: ['comments', variables.task_id] });
      toast.success('Comentário adicionado com sucesso');
    },
    onError: (error) => {
      console.error('Erro na mutação de criar comentário:', error);
      toast.error('Falha ao criar comentário', {
        description: error instanceof Error ? error.message : 'Erro desconhecido',
      });
    },
  });
}

