import React, { useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { ChartContainer, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Project } from '../../contexts/ProjectContext';
import { Users, User, Trophy, Clock, CheckCircle, AlertTriangle } from 'lucide-react';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';

interface TeamAnalyticsProps {
  projects: Project[];
  dateRange: number;
  selectedProject: string;
}

const TeamAnalytics: React.FC<TeamAnalyticsProps> = ({
  projects,
  dateRange,
  selectedProject
}) => {
  const filteredProjects = selectedProject === 'all' 
    ? projects 
    : projects.filter(p => p.id === selectedProject);

  const teamMetrics = useMemo(() => {
    const memberStats = new Map();

    filteredProjects.forEach(project => {
      project.members.forEach(member => {
        if (!memberStats.has(member.id)) {
          memberStats.set(member.id, {
            id: member.id,
            name: member.name,
            projects: [],
            totalTasks: 0,
            completedTasks: 0,
            inProgressTasks: 0,
            overdueTasks: 0,
            highPriorityTasks: 0
          });
        }

        const stats = memberStats.get(member.id);
        stats.projects.push(project.name);

        // Contar tarefas atribuídas a este membro
        const memberTasks = project.tasks.filter(task => task.assignedTo === member.id);
        stats.totalTasks += memberTasks.length;
        stats.completedTasks += memberTasks.filter(t => t.status === 'done').length;
        stats.inProgressTasks += memberTasks.filter(t => t.status === 'doing').length;
        stats.overdueTasks += memberTasks.filter(t => 
          t.dueDate && new Date(t.dueDate) < new Date() && t.status !== 'done'
        ).length;
        stats.highPriorityTasks += memberTasks.filter(t => t.priority === 'high').length;
      });
    });

    const teamData = Array.from(memberStats.values()).map(member => ({
      ...member,
      completionRate: member.totalTasks > 0 ? (member.completedTasks / member.totalTasks) * 100 : 0,
      efficiency: member.totalTasks > 0 ? (member.completedTasks / (member.completedTasks + member.overdueTasks + 0.1)) * 100 : 0,
      projectCount: [...new Set(member.projects)].length
    }));

    // Estatísticas gerais
    const totalMembers = teamData.length;
    const avgTasksPerMember = teamData.reduce((acc, m) => acc + m.totalTasks, 0) / Math.max(totalMembers, 1);
    const avgCompletionRate = teamData.reduce((acc, m) => acc + m.completionRate, 0) / Math.max(totalMembers, 1);
    const topPerformer = teamData.reduce((top, current) => 
      current.completionRate > top.completionRate ? current : top, teamData[0] || { name: 'N/A', completionRate: 0 });

    // Dados para gráficos
    const memberProductivity = teamData.slice(0, 10).map(member => ({
      name: typeof member.name === 'string' ? member.name.split('@')[0] : member.name,
      completed: member.completedTasks,
      inProgress: member.inProgressTasks,
      total: member.totalTasks
    }));

    const workloadDistribution = teamData.map(member => ({
      name: typeof member.name === 'string' ? member.name.split('@')[0] : member.name,
      value: member.totalTasks,
      color: member.totalTasks > avgTasksPerMember ? '#ef4444' : '#22c55e'
    }));

    return {
      teamData,
      totalMembers,
      avgTasksPerMember,
      avgCompletionRate,
      topPerformer,
      memberProductivity,
      workloadDistribution
    };
  }, [filteredProjects]);

  const chartConfig = {
    completed: { label: 'Concluídas', color: '#22c55e' },
    inProgress: { label: 'Em Progresso', color: '#3b82f6' },
    total: { label: 'Total', color: '#6b7280' }
  };

  return (
    <div className="space-y-6">
      {/* Métricas da Equipe */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="animate-fade-in">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total de Membros</CardTitle>
            <Users className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{teamMetrics.totalMembers}</div>
            <p className="text-xs text-muted-foreground">
              membros ativos
            </p>
          </CardContent>
        </Card>

        <Card className="animate-fade-in" style={{ animationDelay: '0.1s' }}>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Tarefas por Membro</CardTitle>
            <User className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{Math.round(teamMetrics.avgTasksPerMember)}</div>
            <p className="text-xs text-muted-foreground">
              média por pessoa
            </p>
          </CardContent>
        </Card>

        <Card className="animate-fade-in" style={{ animationDelay: '0.2s' }}>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Produtividade Média</CardTitle>
            <Clock className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{Math.round(teamMetrics.avgCompletionRate)}%</div>
            <Progress value={teamMetrics.avgCompletionRate} className="mt-2" />
          </CardContent>
        </Card>

        <Card className="animate-fade-in" style={{ animationDelay: '0.3s' }}>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Top Performer</CardTitle>
            <Trophy className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-sm font-bold truncate">
              {typeof teamMetrics.topPerformer?.name === 'string' 
                ? teamMetrics.topPerformer.name.split('@')[0] 
                : teamMetrics.topPerformer?.name || 'N/A'}
            </div>
            <div className="text-xs text-muted-foreground">
              {Math.round(teamMetrics.topPerformer?.completionRate || 0)}% conclusão
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Gráficos */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Produtividade Individual */}
        <Card className="animate-fade-in" style={{ animationDelay: '0.4s' }}>
          <CardHeader>
            <CardTitle>Produtividade por Membro</CardTitle>
          </CardHeader>
          <CardContent>
            <ChartContainer config={chartConfig} className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={teamMetrics.memberProductivity}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="name" angle={-45} textAnchor="end" height={60} />
                  <YAxis />
                  <ChartTooltip content={<ChartTooltipContent />} />
                  <Bar dataKey="completed" fill="#22c55e" />
                  <Bar dataKey="inProgress" fill="#3b82f6" />
                </BarChart>
              </ResponsiveContainer>
            </ChartContainer>
          </CardContent>
        </Card>

        {/* Distribuição de Carga de Trabalho */}
        <Card className="animate-fade-in" style={{ animationDelay: '0.5s' }}>
          <CardHeader>
            <CardTitle>Distribuição de Carga de Trabalho</CardTitle>
          </CardHeader>
          <CardContent>
            <ChartContainer config={chartConfig} className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={teamMetrics.workloadDistribution.filter(item => item.value > 0)}
                    cx="50%"
                    cy="50%"
                    labelLine={false}
                    label={({ name, value }) => `${name}: ${value}`}
                    outerRadius={80}
                    fill="#8884d8"
                    dataKey="value"
                  >
                    {teamMetrics.workloadDistribution.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.color} />
                    ))}
                  </Pie>
                  <ChartTooltip content={<ChartTooltipContent />} />
                </PieChart>
              </ResponsiveContainer>
            </ChartContainer>
          </CardContent>
        </Card>
      </div>

      {/* Ranking da Equipe */}
      <Card className="animate-fade-in" style={{ animationDelay: '0.6s' }}>
        <CardHeader>
          <CardTitle>Ranking da Equipe</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {teamMetrics.teamData
              .sort((a, b) => b.completionRate - a.completionRate)
              .slice(0, 10)
              .map((member, index) => (
                <div key={member.name} className="flex items-center justify-between p-3 border rounded-lg">
                  <div className="flex items-center space-x-4">
                    <div className="flex items-center justify-center w-8 h-8 rounded-full bg-primary text-primary-foreground text-sm font-bold">
                      {index + 1}
                    </div>
                    <div>
                      <p className="font-medium">{typeof member.name === 'string' ? member.name.split('@')[0] : member.name}</p>
                      <p className="text-sm text-muted-foreground">
                        {member.projectCount} projeto{member.projectCount !== 1 ? 's' : ''}
                      </p>
                    </div>
                  </div>
                  
                  <div className="flex items-center space-x-4">
                    <div className="text-right">
                      <p className="text-sm font-medium">{member.totalTasks} tarefas</p>
                      <p className="text-xs text-muted-foreground">
                        {member.completedTasks} concluídas
                      </p>
                    </div>
                    
                    <div className="text-right">
                      <Badge variant={member.completionRate >= 80 ? 'default' : member.completionRate >= 60 ? 'secondary' : 'destructive'}>
                        {Math.round(member.completionRate)}%
                      </Badge>
                      {member.overdueTasks > 0 && (
                        <p className="text-xs text-red-500 mt-1">
                          {member.overdueTasks} atrasadas
                        </p>
                      )}
                    </div>
                  </div>
                </div>
              ))}
          </div>
        </CardContent>
      </Card>

      {/* Insights da Equipe */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        <Card className="animate-fade-in" style={{ animationDelay: '0.7s' }}>
          <CardHeader>
            <CardTitle className="text-lg">Membros Mais Produtivos</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {teamMetrics.teamData
                .filter(m => m.completionRate >= 80)
                .slice(0, 3)
                .map((member, index) => (
                  <div key={member.name} className="flex items-center justify-between">
                    <span className="text-sm truncate flex-1">
                      {typeof member.name === 'string' ? member.name.split('@')[0] : member.name}
                    </span>
                    <Badge variant="default">
                      {Math.round(member.completionRate)}%
                    </Badge>
                  </div>
                ))}
            </div>
          </CardContent>
        </Card>

        <Card className="animate-fade-in" style={{ animationDelay: '0.8s' }}>
          <CardHeader>
            <CardTitle className="text-lg">Sobrecarga de Trabalho</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {teamMetrics.teamData
                .filter(m => m.totalTasks > teamMetrics.avgTasksPerMember * 1.5)
                .slice(0, 3)
                .map((member, index) => (
                  <div key={member.name} className="flex items-center justify-between">
                    <span className="text-sm truncate flex-1">
                      {typeof member.name === 'string' ? member.name.split('@')[0] : member.name}
                    </span>
                    <Badge variant="destructive">
                      {member.totalTasks} tarefas
                    </Badge>
                  </div>
                ))}
            </div>
          </CardContent>
        </Card>

        <Card className="animate-fade-in" style={{ animationDelay: '0.9s' }}>
          <CardHeader>
            <CardTitle className="text-lg">Tarefas Prioritárias</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {teamMetrics.teamData
                .filter(m => m.highPriorityTasks > 0)
                .sort((a, b) => b.highPriorityTasks - a.highPriorityTasks)
                .slice(0, 3)
                .map((member, index) => (
                  <div key={member.name} className="flex items-center justify-between">
                    <span className="text-sm truncate flex-1">
                      {typeof member.name === 'string' ? member.name.split('@')[0] : member.name}
                    </span>
                    <Badge variant="secondary">
                      {member.highPriorityTasks} alta prioridade
                    </Badge>
                  </div>
                ))}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Lista de Membros */}
      <Card>
        <CardHeader>
          <CardTitle>Membros da Equipe</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {filteredProjects.map(project => (
              project.members?.map(member => {
                // Criar uma chave única usando o ID do projeto e um identificador único do membro
                const memberKey = member.id 
                  ? `${project.id}-${member.id}`
                  : `${project.id}-${member.email || member.name || Math.random()}`;
                
                return (
                  <div key={memberKey} className="flex items-center justify-between p-4 border rounded-lg">
                    <div className="flex items-center space-x-4">
                      <Avatar>
                        <AvatarImage src={member.avatar_url} />
                        <AvatarFallback>{member.name?.charAt(0) || '?'}</AvatarFallback>
                      </Avatar>
                      <div>
                        <p className="font-medium">{member.name || 'Sem nome'}</p>
                        <p className="text-sm text-muted-foreground">{member.email || 'Sem email'}</p>
                      </div>
                    </div>
                    <div className="flex items-center space-x-4">
                      <Badge variant={member.status === 'active' ? 'default' : 'secondary'}>
                        {member.status === 'active' ? 'Ativo' : 'Inativo'}
                      </Badge>
                      <Badge variant="outline">{member.role || 'Sem função'}</Badge>
                    </div>
                  </div>
                );
              })
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default TeamAnalytics;
