
import React from 'react';
import { useAuth } from '../../contexts/SupabaseAuthContext';
import { Button } from '@/components/ui/button';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { useIsMobile } from '@/hooks/use-mobile';
import { cn } from '@/lib/utils';
import { LogOut, Settings, User } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import NotificationCenter from '../notifications/NotificationCenter';

const Navbar = () => {
  const { user, logout } = useAuth();
  const isMobile = useIsMobile();
  const navigate = useNavigate();

  const handleProfileClick = () => {
    navigate('/profile');
  };

  const handleSettingsClick = () => {
    navigate('/settings');
  };

  return (
    <nav className="glass-effect border-b border-border/50 px-4 md:px-6 py-4 sticky top-0 z-50">
      <div className="flex items-center justify-between">
        <div className={cn("flex items-center space-x-4", isMobile && "ml-12")}>
          <div className="flex items-center space-x-3">
            <img 
              src="/lovable-uploads/6a8c398e-4ec1-41d5-adf1-556d3b24b5d6.png" 
              alt="Imi Gestão" 
              className="h-10 w-10 object-contain" 
            />
            <h1 className="text-xl md:text-2xl font-bold gradient-primary bg-clip-text text-transparent">
              IMI Gestão
            </h1>
          </div>
          {user && (
            <div className="hidden md:flex items-center space-x-2 text-sm text-muted-foreground">
              <span>•</span>
              <span className="capitalize">{user.role}</span>
              {user.organizationId && (
                <>
                  <span>•</span>
                  <span>{user.organizationId}</span>
                </>
              )}
            </div>
          )}
        </div>

        <div className="flex items-center space-x-2 md:space-x-4">
          <NotificationCenter />
          
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" className="relative h-10 w-10 rounded-full hover:bg-accent/50 transition-colors">
                <Avatar className="h-10 w-10 border-2 border-primary/20">
                  <AvatarImage src={user?.avatar} alt={user?.name} />
                  <AvatarFallback className="gradient-primary text-white text-sm font-medium">
                    {user?.name?.charAt(0).toUpperCase()}
                  </AvatarFallback>
                </Avatar>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent className="w-56 glass-effect border-border/50" align="end" forceMount>
              <DropdownMenuLabel className="font-normal">
                <div className="flex flex-col space-y-1">
                  <p className="text-sm font-medium leading-none">{user?.name}</p>
                  <p className="text-xs leading-none text-muted-foreground">
                    {user?.email}
                  </p>
                </div>
              </DropdownMenuLabel>
              <DropdownMenuSeparator className="bg-border/50" />
              <DropdownMenuItem onClick={handleProfileClick} className="cursor-pointer hover:bg-accent/50 transition-colors">
                <User className="mr-2 h-4 w-4" />
                <span>Perfil</span>
              </DropdownMenuItem>
              <DropdownMenuItem onClick={handleSettingsClick} className="cursor-pointer hover:bg-accent/50 transition-colors">
                <Settings className="mr-2 h-4 w-4" />
                <span>Configurações</span>
              </DropdownMenuItem>
              <DropdownMenuSeparator className="bg-border/50" />
              <DropdownMenuItem onClick={logout} className="cursor-pointer hover:bg-destructive/10 text-destructive focus:text-destructive transition-colors">
                <LogOut className="mr-2 h-4 w-4" />
                <span>Sair</span>
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
