import { useState } from 'react';
import { useAuth } from '@/contexts/SupabaseAuthContext';
import { useProject } from '@/contexts/ProjectContext';
import { useUserTasks } from '@/hooks/useTaskQueries';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import TaskDetailDialog from '@/components/tasks/TaskDetailDialog';
import { Database } from '@/integrations/supabase/types';

type Task = Database['public']['Tables']['tasks']['Row'] & {
  projectName: string;
};

export default function Tasks() {
  const { user } = useAuth();
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [filter, setFilter] = useState<'all' | 'overdue'>('all');

  // Buscar projetos do usuário
  const { projects = [] } = useProject();
  const projectIds = projects.map(p => p.id);

  // Buscar tarefas dos projetos
  const { data: tasks = [], isLoading, error } = useUserTasks(projectIds);

  // Filtrar tarefas
  const filteredTasks = tasks.filter(task => {
    if (filter === 'overdue') {
      return task.due_date && new Date(task.due_date) < new Date();
    }
    return true;
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container mx-auto py-6">
        <div className="text-center py-8">
          <p className="text-red-500">Erro ao carregar tarefas. Tente novamente.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto py-6 space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold">Tarefas</h1>
        <Tabs value={filter} onValueChange={(value) => setFilter(value as 'all' | 'overdue')}>
          <TabsList>
            <TabsTrigger value="all">Todas</TabsTrigger>
            <TabsTrigger value="overdue">Atrasadas</TabsTrigger>
          </TabsList>
        </Tabs>
      </div>

      <div className="grid gap-4">
        {filteredTasks.map((task) => (
          <Card key={task.id} className="cursor-pointer hover:bg-accent/50 transition-colors" onClick={() => setSelectedTask(task)}>
            <CardHeader className="pb-2">
              <div className="flex justify-between items-start">
                <div>
                  <CardTitle className="text-lg">{task.title}</CardTitle>
                  <p className="text-sm text-muted-foreground">{task.projectName}</p>
                </div>
                <div className="flex gap-2">
                  <Badge className={task.status === 'done' ? 'bg-green-500' : task.status === 'doing' ? 'bg-blue-500' : 'bg-gray-500'}>
                    {task.status === 'done' ? 'Concluída' : task.status === 'doing' ? 'Em andamento' : 'A fazer'}
                  </Badge>
                  <Badge className={task.priority === 'high' ? 'bg-red-500' : task.priority === 'medium' ? 'bg-yellow-500' : 'bg-green-500'}>
                    {task.priority === 'high' ? 'Alta' : task.priority === 'medium' ? 'Média' : 'Baixa'}
                  </Badge>
                </div>
              </div>
            </CardHeader>
            <CardContent>
              <p className="text-sm text-muted-foreground line-clamp-2">{task.description}</p>
              {task.due_date && (
                <p className="text-sm text-muted-foreground mt-2">
                  Prazo: {new Date(task.due_date).toLocaleDateString()}
                </p>
              )}
            </CardContent>
          </Card>
        ))}

        {filteredTasks.length === 0 && (
          <div className="text-center py-8">
            <p className="text-muted-foreground">Nenhuma tarefa encontrada.</p>
          </div>
        )}
      </div>

      {selectedTask && (
        <TaskDetailDialog
          open={!!selectedTask}
          onOpenChange={(open) => !open && setSelectedTask(null)}
          task={selectedTask}
          projectId={selectedTask.project_id}
        />
      )}
    </div>
  );
} 