import { createClient } from '@supabase/supabase-js';
import { Database } from '@/integrations/supabase/types';
import { logger } from './logger';

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseAnonKey) {
  throw new Error('Supabase URL and Anon Key must be defined in environment variables');
}

// Controle de refresh para evitar múltiplas chamadas
let lastRefreshTime = 0;
const MIN_REFRESH_INTERVAL = 10000; // 10 segundos
let refreshPromise: Promise<any> | null = null;
let isRefreshing = false;

// Criar cliente Supabase
export const supabase = createClient<Database>(supabaseUrl, supabaseAnonKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    storageKey: 'project-hive-auth',
    storage: {
      getItem: (key) => {
        const value = localStorage.getItem(key);
        if (!value) return null;
        try {
          const parsed = JSON.parse(value);
          const now = Date.now();
          
          // Verificar se o token está próximo de expirar (5 minutos)
          if (parsed.expires_at && parsed.expires_at - now < 300000) {
            // Agendar verificação de sessão
            setTimeout(() => {
              const currentTime = Date.now();
              // Evitar múltiplos refreshes simultâneos
              if (!isRefreshing && currentTime - lastRefreshTime > MIN_REFRESH_INTERVAL) {
                isRefreshing = true;
                lastRefreshTime = currentTime;
                
                supabase.auth.refreshSession()
                  .then(() => {
                    logger.info('Token atualizado com sucesso', { context: 'Auth' });
                  })
                  .catch((error) => {
                    logger.error('Erro ao atualizar token:', error, { context: 'Auth' });
                  })
                  .finally(() => {
                    isRefreshing = false;
                  });
              }
            }, 0);
          }
          return value;
        } catch (error) {
          logger.error('Erro ao parsear token:', error, { context: 'Auth' });
          return null;
        }
      },
      setItem: (key, value) => localStorage.setItem(key, value),
      removeItem: (key) => localStorage.removeItem(key)
    }
  },
  realtime: {
    params: {
      eventsPerSecond: 10
    },
    retryAfter: 2000,
    maxRetries: 3,
    timeout: 15000
  },
  global: {
    headers: {
      'x-application-name': 'project-hive'
    }
  }
});

// Função para verificar a conexão
export async function checkSupabaseConnection() {
  try {
    const { data, error } = await supabase.from('profiles').select('count').limit(1);
    if (error) throw error;
    logger.debug('Verificando conexão com Supabase', { context: 'Supabase' });
    logger.info('Conexão com Supabase verificada', { isConnected: true }, { context: 'Supabase' });
    return true;
  } catch (error) {
    logger.error('Erro ao verificar conexão com Supabase', { error }, { context: 'Supabase', showToast: true });
    return false;
  }
}

// Função para reconectar
export async function reconnectSupabase() {
  try {
    // Verificar se já está em processo de refresh
    if (isRefreshing) {
      logger.debug('Já existe um processo de refresh em andamento', { context: 'Supabase' });
      return true;
    }
    
    isRefreshing = true;
    lastRefreshTime = Date.now();
    
    logger.debug('Iniciando reconexão com Supabase', { context: 'Supabase' });
    
    const { error } = await supabase.auth.refreshSession();
    if (error) throw error;
    
    logger.info('Reconexão com Supabase realizada', { context: 'Supabase' });
    return await checkSupabaseConnection();
  } catch (error) {
    logger.error('Erro na reconexão com Supabase', { error }, { context: 'Supabase', showToast: true });
    return false;
  } finally {
    isRefreshing = false;
  }
}

// Função wrapper para operações do Supabase com retry
export async function withRetry<T>(
  operation: () => Promise<{ data: T | null; error: any }>,
  maxRetries = 3,
  delay = 1000
): Promise<{ data: T | null; error: any }> {
  let retries = 0;
  
  while (retries < maxRetries) {
    try {
      const result = await operation();
      if (result.error) {
        if (result.error.message?.includes('connection') || result.error.message?.includes('network')) {
          retries++;
          if (retries < maxRetries) {
            await new Promise(resolve => setTimeout(resolve, delay * retries));
            continue;
          }
        }
      }
      return result;
    } catch (error) {
      retries++;
      if (retries < maxRetries) {
        await new Promise(resolve => setTimeout(resolve, delay * retries));
        continue;
      }
      return { data: null, error };
    }
  }
  
  return { data: null, error: new Error('Número máximo de tentativas excedido') };
}

// Exporta funções auxiliares
export const supabaseHelpers = {
  checkConnection: checkSupabaseConnection,
  reconnect: reconnectSupabase,
  withRetry
};

// Funções auxiliares para trabalhar com o Supabase
export const getProfile = async (userId: string) => {
  const { data, error } = await supabase
    .from('profiles')
    .select('*')
    .eq('id', userId)
    .single();

  if (error) throw error;
  return data;
};

