export async function addComment(comment: Database['public']['Tables']['comments']['Insert']) {
  try {
    // Verificar se há uma sessão ativa antes de prosseguir
    const { data: sessionData } = await supabase.auth.getSession();
    if (!sessionData.session) {
      // Tentar renovar a sessão se não houver uma ativa
      const { error: refreshError } = await supabase.auth.refreshSession();
      if (refreshError) {
        logger.error('Erro ao renovar sessão antes de adicionar comentário', { error: refreshError });
        throw new Error('Sessão expirada. Por favor, faça login novamente.');
      }
    }
    
    // Verificar se project_id está presente
    if (!comment.project_id) {
      logger.error('Tentativa de adicionar comentário sem project_id', { comment });
      throw new Error('project_id é obrigatório para adicionar um comentário');
    }

    const { data, error } = await supabase
      .from('comments')
      .insert(comment)
      .select('*')
      .single();

    if (error) throw error;
    return data;
  } catch (error) {
    logger.error('Erro ao adicionar comentário', { error, comment });
    throw error;
  }
}

