import { useState, useEffect } from 'react';
import { useProject } from '../../contexts/ProjectContext';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { MessageSquare, Send, Trash2 } from 'lucide-react';
import { useAuth } from '../../contexts/SupabaseAuthContext';
import { Database } from '@/integrations/supabase/types';
import { supabase, addComment } from '@/lib/supabase';
import { useDeleteComment } from '@/hooks/useSupabaseMutations';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { queryKeys } from '@/lib/queryKeys';

type Profile = Database['public']['Tables']['profiles']['Row'];
type Comment = Database['public']['Tables']['comments']['Row'] & {
  profiles?: Profile;
};

interface TaskCommentsProps {
  taskId: string;
  projectId: string;
  comments: Comment[];
}

const TaskComments = ({ taskId, projectId, comments }: TaskCommentsProps) => {
  const { user } = useAuth();
  const [newComment, setNewComment] = useState('');
  const [authors, setAuthors] = useState<Record<string, Profile>>({});
  const queryClient = useQueryClient();

  const deleteComment = useDeleteComment();

  const { data: taskComments = comments || [] } = useQuery({
    queryKey: queryKeys.comments(taskId),
    queryFn: async () => {
      if (!taskId) return [];
      
      const { data, error } = await supabase
        .from('comments')
        .select(`
          *,
          profiles:created_by(*)
        `)
        .eq('task_id', taskId)
        .order('created_at', { ascending: true });

      if (error) throw error;
      return data as Comment[];
    },
    initialData: comments,
    enabled: !!taskId
  });

  // Carregar autores dos comentários
  useEffect(() => {
    const fetchAuthors = async () => {
      const authorIds = [...new Set(taskComments.map(comment => comment.created_by))];
      if (authorIds.length === 0) return;

      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .in('id', authorIds);

      if (error) {
        console.error('[Comments] Erro ao buscar autores:', error);
        return;
      }

      const authorsMap = data.reduce((acc, author) => {
        acc[author.id] = author;
        return acc;
      }, {} as Record<string, Profile>);

      setAuthors(authorsMap);
    };

    fetchAuthors();
  }, [taskComments]);

  const handleSubmitComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user || !newComment.trim()) {
      if (!user) {
        toast.error('Você precisa estar logado para comentar');
      }
      return;
    }

    try {
      // Validar se temos o project_id
      if (!projectId) {
        console.error('[Comments] project_id não fornecido');
        toast.error('ID do projeto não disponível');
        return;
      }

      // Verificar se o usuário é membro do projeto
      try {
        // Verificar sessão antes de prosseguir
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData.session) {
          // Tentar renovar a sessão
          const { error: refreshError } = await supabase.auth.refreshSession();
          if (refreshError) {
            toast.error('Sessão expirada. Por favor, faça login novamente.');
            return;
          }
        }

        const { data: isMember, error: memberError } = await supabase
          .from('project_members')
          .select('project_id, user_id')
          .eq('project_id', projectId)
          .eq('user_id', user.id)
          .single();

        if (memberError || !isMember) {
          console.error('[Comments] Usuário não é membro do projeto:', memberError);
          toast.error('Você não tem permissão para comentar nesta tarefa');
          return;
        }
      } catch (error) {
        console.error('Erro ao verificar permissão do usuário:', error);
        toast.error('Não foi possível verificar suas permissões');
        return;
      }

      // Criar o comentário com todos os campos obrigatórios
      const commentData = {
        content: newComment.trim(),
        task_id: taskId,
        project_id: projectId,
        created_by: user.id,
        created_at: new Date().toISOString()
      };

      console.log('[DEBUG] Payload do comentário:', JSON.stringify(commentData, null, 2));
      console.log('[DEBUG] Tipos dos campos:', {
        content: typeof commentData.content,
        task_id: typeof commentData.task_id,
        project_id: typeof commentData.project_id,
        created_by: typeof commentData.created_by,
        created_at: typeof commentData.created_at
      });

      await addComment(commentData);
      toast.success('Comentário adicionado com sucesso');

      setNewComment('');
      queryClient.invalidateQueries({ queryKey: queryKeys.comments(taskId) });
    } catch (error) {
      console.error('[Comments] Erro ao adicionar comentário:', {
        error,
        message: error.message,
        details: error.details,
        hint: error.hint,
        code: error.code
      });
      toast.error('Falha ao adicionar comentário: ' + (error.message || 'Erro desconhecido'));
    }
  };

  const handleDeleteComment = async (commentId: string) => {
    try {
      await deleteComment.mutateAsync(commentId);
    } catch (error) {
      console.error('[Comments] Erro ao excluir comentário:', error);
    }
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center">
          <MessageSquare className="mr-2 h-5 w-5" />
          Comentários
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          <div className="max-h-[400px] overflow-y-auto pr-2 space-y-4">
          {taskComments.map((comment) => (
            <div key={comment.id} className="p-3 bg-muted rounded-lg">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium">
                  {authors[comment.created_by]?.name || 'Usuário'}
                </span>
                  <div className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground">
                  {new Date(comment.created_at || '').toLocaleDateString('pt-BR', {
                    day: '2-digit',
                    month: '2-digit',
                    year: 'numeric',
                    hour: '2-digit',
                    minute: '2-digit'
                  })}
                </span>
                    {(user?.id === comment.created_by || user?.role === 'admin') && (
                      <Button
                        onClick={() => handleDeleteComment(comment.id)}
                        className="h-6 w-6 p-0 hover:bg-destructive hover:text-destructive-foreground"
                        disabled={deleteComment.isPending}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    )}
                  </div>
              </div>
              <p className="text-sm break-words whitespace-pre-line max-h-24 overflow-y-auto">{comment.content}</p>
            </div>
          ))}
          </div>

          <form onSubmit={handleSubmitComment} className="space-y-4">
            <Textarea
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              placeholder="Digite seu comentário..."
              className="min-h-[100px]"
            />
            <div className="flex justify-end">
              <Button 
                type="submit" 
                disabled={!newComment.trim()}
                className="flex items-center gap-2"
              >
                <Send className="h-4 w-4" />
                Enviar
              </Button>
            </div>
          </form>
        </div>
      </CardContent>
    </Card>
  );
};

export default TaskComments;
