import { useEffect, useRef } from 'react';
import { logger } from '@/lib/logger';

interface UsePageVisibilityOptions {
  onPageVisible?: () => void;
  onPageHidden?: () => void;
  debounceMs?: number;
}

export function usePageVisibility(options: UsePageVisibilityOptions = {}) {
  const { onPageVisible, onPageHidden, debounceMs = 500 } = options;
  const timeoutRef = useRef<NodeJS.Timeout>();
  const wasHiddenRef = useRef(false);

  useEffect(() => {
    const handleVisibilityChange = () => {
      // Limpa timeout anterior se existir
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }

      if (document.hidden) {
        // Página ficou oculta
        wasHiddenRef.current = true;
        onPageHidden?.();
      } else {
        // Página ficou visível
        if (wasHiddenRef.current) {
          // Só executa se a página estava oculta antes
          timeoutRef.current = setTimeout(() => {
            onPageVisible?.();
            wasHiddenRef.current = false;
          }, debounceMs);
        }
      }
    };

    // Eventos para detectar quando usuário sai/volta da página
    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('focus', handleVisibilityChange);
    window.addEventListener('blur', () => {
      wasHiddenRef.current = true;
      onPageHidden?.();
    });

    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('focus', handleVisibilityChange);
      window.removeEventListener('blur', handleVisibilityChange);
      
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [onPageVisible, onPageHidden, debounceMs]);

  return {
    isVisible: !document.hidden,
    wasHidden: wasHiddenRef.current
  };
} 