import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useProject } from '@/contexts/ProjectContext';
import { useProjectTasks } from '@/hooks/useProjectTasks';
import ProjectHeader from './ProjectHeader';
import ProjectTaskList from './ProjectTaskList';
import ProjectStats from './ProjectStats';
import TaskDialog from '../tasks/TaskDialog';
import TaskDetailDialog from '../tasks/TaskDetailDialog';
import { Card } from '../ui/card';
import TeamMembers from './TeamMembers';
import { Database } from '@/integrations/supabase/types';
import { toast } from 'sonner';
import { logger } from '@/lib/logger';
import { Button } from '../ui/button';
import { Loader2, RefreshCw } from 'lucide-react';

type Project = Database['public']['Tables']['projects']['Row'] & {
  members?: Database['public']['Tables']['project_members']['Row'][];
  tasks?: Task[];
};

type Task = Database['public']['Tables']['tasks']['Row'] & {
  tags?: string[];
  comments?: Database['public']['Tables']['comments']['Row'][];
};

// 🔍 SISTEMA DE DEBUG COMPLETO
const DEBUG_PREFIX = '[ProjectDetail-DEBUG]';
const debugLog = (message: string, data?: any) => {
  console.log(`${DEBUG_PREFIX} ${message}`, data ? data : '');
};

const debugWarn = (message: string, data?: any) => {
  console.warn(`${DEBUG_PREFIX} ⚠️ ${message}`, data ? data : '');
};

const debugError = (message: string, data?: any) => {
  console.error(`${DEBUG_PREFIX} ❌ ${message}`, data ? data : '');
};

const ProjectDetail = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { getProject } = useProject();
  
  // 🔍 DEBUG: Contador de renders
  const renderCountRef = useRef(0);
  renderCountRef.current += 1;
  
  debugLog(`🔄 RENDER #${renderCountRef.current}`, { id, timestamp: new Date().toISOString() });

  // Estados
  const [project, setProject] = useState<Project | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState(0);
  const [isRetrying, setIsRetrying] = useState(false);
  const isMountedRef = useRef(true);
  const loadingTimeoutRef = useRef<NodeJS.Timeout>();
  // Estados para diálogos de tarefa
  const [isTaskDialogOpen, setIsTaskDialogOpen] = useState(false);
  const [isTaskDetailOpen, setIsTaskDetailOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);

  const MAX_RETRIES = 3;
  const LOADING_TIMEOUT = 30000; // 30 segundos

  const loadProject = useCallback(async (isRetry = false) => {
    if (!id) return;

    if (isRetry) {
      setIsRetrying(true);
    } else {
      setLoading(true);
    }
    setError(null);

    try {
      // Limpar timeout anterior se existir
      if (loadingTimeoutRef.current) {
        clearTimeout(loadingTimeoutRef.current);
      }

      // Configurar novo timeout
      loadingTimeoutRef.current = setTimeout(() => {
        if (isMountedRef.current) {
          setError('Tempo limite excedido ao carregar o projeto');
          setLoading(false);
          setIsRetrying(false);
        }
      }, LOADING_TIMEOUT);

      logger.debug('Iniciando carregamento do projeto', {
        projectId: id,
        isRetry,
        retryCount,
        context: 'ProjectDetail'
      });

      const projectData = await getProject(id);

      if (!isMountedRef.current) return;

      if (!projectData) {
        throw new Error('Projeto não encontrado');
      }

      setProject(projectData);
      setError(null);
      setRetryCount(0);

      logger.info('Projeto carregado com sucesso', {
        projectId: id,
        context: 'ProjectDetail'
      });

    } catch (error: any) {
      if (!isMountedRef.current) return;

      logger.error('Erro ao carregar projeto', {
        error: error.message,
        projectId: id,
        retryCount,
        context: 'ProjectDetail'
      });

      setError(error.message || 'Erro ao carregar projeto');

      if (retryCount < MAX_RETRIES) {
        const delay = Math.min(1000 * Math.pow(2, retryCount), 10000);
        logger.debug('Aguardando antes de nova tentativa', {
          projectId: id,
          retryCount: retryCount + 1,
          delay,
          context: 'ProjectDetail'
        });

        setTimeout(() => {
          if (isMountedRef.current) {
            setRetryCount(prev => prev + 1);
            loadProject(true);
          }
        }, delay);
      }
    } finally {
      if (isMountedRef.current) {
        setLoading(false);
        setIsRetrying(false);
        if (loadingTimeoutRef.current) {
          clearTimeout(loadingTimeoutRef.current);
        }
      }
    }
  }, [id, getProject, retryCount]);

  useEffect(() => {
    isMountedRef.current = true;
    loadProject();

    return () => {
      isMountedRef.current = false;
      if (loadingTimeoutRef.current) {
        clearTimeout(loadingTimeoutRef.current);
      }
    };
  }, [loadProject]);

  const handleRetry = () => {
    setRetryCount(0);
    loadProject(true);
  };

  // 🔍 DEBUG: Monitorar mudanças de estado
  useEffect(() => {
    debugLog('📊 Estado atual:', {
      id,
      hasProject: !!project,
      projectId: project?.id,
      loading,
      error,
      retryCount
    });
  }, [id, project, loading, error, retryCount]);

  // Hook das tarefas
  debugLog('🎯 Executando useProjectTasks com:', project?.id);
  const { data: tasks = [], isLoading: isLoadingTasks } = useProjectTasks(project?.id);
  
  // 🔍 DEBUG: Monitorar mudanças nas tasks
  useEffect(() => {
    debugLog('📋 Tasks carregadas:', {
      projectId: project?.id,
      tasksCount: tasks.length,
      isLoadingTasks,
      taskIds: tasks.map(t => t.id)
    });
  }, [tasks, isLoadingTasks, project?.id]);

  // 🔍 DEBUG: Monitorar mudanças no ID
  const previousIdRef = useRef<string>();
  useEffect(() => {
    if (previousIdRef.current !== id) {
      debugLog('🔄 ID MUDOU:', {
        anterior: previousIdRef.current,
        novo: id,
        timestamp: new Date().toISOString()
      });
      previousIdRef.current = id;
    }
  }, [id]);

  // 🔍 DEBUG: Monitorar getProject function
  useEffect(() => {
    debugLog('🔧 getProject function changed', {
      hasGetProject: typeof getProject === 'function'
    });
  }, [getProject]);

  // Cálculos de progresso
  const { completedTasks, progress } = useMemo(() => {
    if (!tasks || tasks.length === 0) {
      debugLog('📊 Progresso: sem tasks');
      return { completedTasks: 0, progress: 0 };
    }
    
    const completed = tasks.filter(t => t.status === 'done').length;
    const progressPercentage = (completed / tasks.length) * 100;
    
    debugLog('📊 Progresso calculado:', {
      total: tasks.length,
      completed,
      progress: progressPercentage
    });
    
    return {
      completedTasks: completed,
      progress: progressPercentage
    };
  }, [tasks]);

  // Event handlers
  const handleTaskClick = useCallback((task: Database['public']['Tables']['tasks']['Row']) => {
    debugLog('🎯 Task clicada:', { taskId: task.id });
    setSelectedTask(task);
    setIsTaskDetailOpen(true);
  }, []);

  const handleNewTask = useCallback(() => {
    debugLog('➕ Nova task solicitada');
    setIsTaskDialogOpen(true);
  }, []);

  // 🔍 DEBUG: Log final antes do render
  debugLog('🎭 RENDER FINAL', {
    loading,
    isLoadingTasks,
    hasError: !!error,
    hasProject: !!project,
    tasksCount: tasks.length
  });

  // Loading state
  if (loading && !isRetrying) {
    debugLog('⏳ Renderizando loading...');
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <Loader2 className="w-8 h-8 animate-spin mx-auto mb-4" />
          <p className="text-lg">Carregando projeto...</p>
        </div>
      </div>
    );
  }

  // Error state
  if (error) {
    debugLog('❌ Renderizando erro...');
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <p className="text-lg text-red-500 mb-4">{error}</p>
          <div className="space-x-4">
            <Button
              onClick={handleRetry}
              disabled={isRetrying}
              className="flex items-center gap-2"
            >
              {isRetrying ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <RefreshCw className="w-4 h-4" />
              )}
              Tentar novamente
            </Button>
            <Button
              variant="outline"
              onClick={() => navigate('/projects')}
            >
              Voltar para projetos
            </Button>
          </div>
        </div>
      </div>
    );
  }

  // Empty state
  if (!project) {
    debugLog('❓ Renderizando projeto não encontrado...');
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <p className="text-gray-500">Projeto não encontrado</p>
          <p className="text-xs text-gray-400">
            Render #{renderCountRef.current} | ID: {id}
          </p>
        </div>
      </div>
    );
  }

  debugLog('✅ Renderizando projeto completo');
  
  return (
    <div className="container mx-auto px-4 py-8">
      {/* 🔍 DEBUG: Info bar no topo */}
      <div className="bg-gray-100 p-2 rounded text-xs text-gray-600">
        Debug Info: Render #{renderCountRef.current} | Project: {project.id} | Tasks: {tasks.length}
      </div>
      
      <ProjectHeader
        project={project}
        progress={progress}
        completedTasks={completedTasks}
        onNewTask={handleNewTask}
      />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mt-6">
        <div className="lg:col-span-2">
          <Card className="p-6">
            <ProjectTaskList
              tasks={tasks}
              onTaskClick={handleTaskClick}
              onNewTask={handleNewTask}
            />
          </Card>
        </div>
        <div className="space-y-6">
          <ProjectStats project={project} />
          <TeamMembers projectId={project.id} />
        </div>
      </div>

      <TaskDialog
        open={isTaskDialogOpen}
        onOpenChange={setIsTaskDialogOpen}
        projectId={project.id}
      />

      <TaskDetailDialog
        open={isTaskDetailOpen}
        onOpenChange={setIsTaskDetailOpen}
        task={selectedTask}
        projectId={project.id}
      />
    </div>
  );
};

export default ProjectDetail;