import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useUpdateTask } from '@/hooks/useTaskMutations';
import { toast } from 'sonner';
import { Task } from '@/contexts/ProjectContext';
import { supabase } from '@/lib/supabase';
import { Database } from '@/integrations/supabase/types';

type ProjectMember = Database['public']['Tables']['project_members']['Row'] & {
  profiles: Database['public']['Tables']['profiles']['Row'];
};

interface EditTaskDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  task: Task | null;
  projectId: string;
}

export const EditTaskDialog: React.FC<EditTaskDialogProps> = ({ open, onOpenChange, task, projectId }) => {
  const updateTask = useUpdateTask();
  const [projectMembers, setProjectMembers] = useState<ProjectMember[]>([]);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    status: 'todo' as 'todo' | 'doing' | 'done',
    priority: 'medium' as 'high' | 'medium' | 'low',
    assigned_to: '',
    due_date: ''
  });

  useEffect(() => {
    const fetchMembers = async () => {
      const { data, error } = await supabase
        .from('project_members')
        .select(`
          *,
          profiles:user_id (
            id,
            name,
            email,
            avatar
          )
        `)
        .eq('project_id', projectId);

      if (error) {
        console.error('[EditTaskDialog] Erro ao buscar membros:', error);
        return;
      }

      setProjectMembers(data || []);
    };

    fetchMembers();
  }, [projectId]);

  useEffect(() => {
    if (task) {
      console.log('[EditTaskDialog] Inicializando formulário com tarefa:', task);
      setFormData({
        title: task.title,
        description: task.description || '',
        status: (task.status as 'todo' | 'doing' | 'done') || 'todo',
        priority: (task.priority as 'high' | 'medium' | 'low') || 'medium',
        assigned_to: task.assigned_to || '',
        due_date: task.due_date || ''
      });
    }
  }, [task]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!task?.id) {
      console.error('[EditTaskDialog] ID da tarefa não encontrado');
      toast.error('Erro ao atualizar tarefa: ID não encontrado');
      return;
    }

    try {
      console.log('[EditTaskDialog] Atualizando tarefa:', { id: task.id, formData });
      
      // Remover campos vazios
      const taskData = Object.fromEntries(
        Object.entries({
          ...formData,
          due_date: formData.due_date || null,
          project_id: projectId
        }).filter(([_, value]) => value !== null && value !== '')
      );

      await updateTask.mutateAsync({ 
        id: task.id, 
        updates: taskData 
      });
      
      onOpenChange(false);
    } catch (error) {
      console.error('[EditTaskDialog] Erro ao atualizar tarefa:', error);
      toast.error('Erro ao atualizar tarefa. Tente novamente.');
    }
  };

  if (!task) return null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Editar Tarefa</DialogTitle>
          <DialogDescription>
            Faça as alterações necessárias na tarefa.
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-medium">Título da Tarefa</label>
            <Input
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
              placeholder="Digite o título da tarefa"
              required
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">Descrição</label>
            <Textarea
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              placeholder="Descreva a tarefa"
              rows={3}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Status</label>
              <Select
                value={formData.status}
                onValueChange={(value: 'todo' | 'doing' | 'done') => 
                  setFormData({ ...formData, status: value })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="todo">A Fazer</SelectItem>
                  <SelectItem value="doing">Em Progresso</SelectItem>
                  <SelectItem value="done">Concluído</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Prioridade</label>
              <Select
                value={formData.priority}
                onValueChange={(value: 'high' | 'medium' | 'low') => 
                  setFormData({ ...formData, priority: value })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="high">Alta</SelectItem>
                  <SelectItem value="medium">Média</SelectItem>
                  <SelectItem value="low">Baixa</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">Responsável</label>
            <Select
              value={formData.assigned_to}
              onValueChange={(value) => setFormData({ ...formData, assigned_to: value })}
            >
              <SelectTrigger>
                <SelectValue placeholder="Selecione o responsável" />
              </SelectTrigger>
              <SelectContent>
                {projectMembers.map((member) => (
                  <SelectItem key={member.user_id} value={member.user_id}>
                    {member.profiles?.name || 'Usuário'}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">Data de Entrega</label>
            <Input
              type="date"
              value={formData.due_date}
              onChange={(e) => setFormData({ ...formData, due_date: e.target.value })}
            />
          </div>

          <div className="flex justify-end space-x-2 pt-4">
            <Button 
              type="button" 
              variant="outline" 
              onClick={() => onOpenChange(false)}
              disabled={updateTask.isPending}
            >
              Cancelar
            </Button>
            <Button 
              type="submit" 
              className="bg-gradient-to-r from-blue-600 to-purple-600"
              disabled={updateTask.isPending}
            >
              {updateTask.isPending ? 'Salvando...' : 'Salvar Alterações'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default EditTaskDialog;
