import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { cn } from '@/lib/utils';
import { Home, FolderOpen, Calendar, Menu, X, BarChart3, Settings } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useIsMobile } from '@/hooks/use-mobile';
import { useAuth } from '../../contexts/SupabaseAuthContext';
import { Drawer, DrawerContent, DrawerHeader, DrawerTitle, DrawerTrigger, DrawerClose } from '@/components/ui/drawer';

const SidebarContent = ({ onNavigate }: { onNavigate?: () => void }) => {
  const location = useLocation();
  const { hasPermission } = useAuth();

  const navigation = [
    { name: 'Dashboard', href: '/dashboard', icon: Home },
    { name: 'Projetos', href: '/projects', icon: FolderOpen },
    { name: 'Tarefas', href: '/tasks', icon: Calendar },
    { name: 'Calendário', href: '/calendar', icon: Calendar },
    ...(hasPermission('view_analytics') ? [{ name: 'Analytics', href: '/analytics', icon: BarChart3 }] : []),
    ...(hasPermission('admin') ? [{ name: 'Administração', href: '/admin', icon: Settings }] : [])
  ];

  return (
    <nav className="flex flex-col space-y-2 p-4">
      {navigation.map((item) => {
        const isActive = location.pathname === item.href || (item.href === '/dashboard' && location.pathname === '/');
        return (
          <Link
            key={item.name}
            to={item.href}
            onClick={onNavigate}
            className={cn(
              'group flex items-center px-4 py-3 text-sm font-medium rounded-lg transition-all duration-200 hover-lift',
              isActive
                ? 'gradient-primary text-white shadow-lg'
                : 'text-muted-foreground hover:text-foreground hover:bg-accent/50'
            )}
          >
            <item.icon
              className={cn(
                'mr-3 flex-shrink-0 h-5 w-5 transition-colors',
                isActive
                  ? 'text-white'
                  : 'text-muted-foreground group-hover:text-foreground'
              )}
            />
            {item.name}
          </Link>
        );
      })}
    </nav>
  );
};

const Sidebar = () => {
  const isMobile = useIsMobile();
  const [open, setOpen] = React.useState(false);

  if (isMobile) {
    return (
      <Drawer open={open} onOpenChange={setOpen}>
        <DrawerTrigger asChild>
          <Button variant="ghost" size="sm" className="fixed top-4 left-4 z-50 glass-effect shadow-lg hover:bg-accent/50">
            <Menu className="h-5 w-5" />
          </Button>
        </DrawerTrigger>
        <DrawerContent className="h-[80vh] bg-background border-border/50">
          <DrawerHeader className="text-left border-b border-border/50">
            <div className="flex items-center justify-between">
              <DrawerTitle className="text-2xl font-bold gradient-primary bg-clip-text text-transparent">
                Menu
              </DrawerTitle>
              <DrawerClose asChild>
                <Button variant="ghost" size="sm" className="hover:bg-accent/50">
                  <X className="h-5 w-5" />
                </Button>
              </DrawerClose>
            </div>
          </DrawerHeader>
          <div className="flex-1 overflow-y-auto">
            <SidebarContent onNavigate={() => setOpen(false)} />
          </div>
        </DrawerContent>
      </Drawer>
    );
  }

  return (
    <div className="hidden md:flex md:w-64 md:flex-col">
      <div className="flex flex-col flex-grow pt-6 pb-4 overflow-y-auto glass-effect border-r border-border/50">
        <div className="flex-grow flex flex-col">
          <SidebarContent />
        </div>
        
        <div className="px-4 py-4 border-t border-border/50 mt-auto">
          <p className="text-xs text-muted-foreground text-center">Imi Gestão Profissional v1.0</p>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;
