import { supabase } from '@/lib/supabase';
import { logger } from '@/lib/logger';

// Intervalos mais agressivos em produção
const PING_INTERVAL = process.env.NODE_ENV === 'production' ? 60 * 1000 : 14 * 60 * 1000; // 1 minuto em produção, 14 minutos em dev
const MAX_RETRIES = process.env.NODE_ENV === 'production' ? 10 : 5;
const RETRY_DELAY = process.env.NODE_ENV === 'production' ? 500 : 5000;
const HEALTH_CHECK_INTERVAL = process.env.NODE_ENV === 'production' ? 5 * 1000 : 60 * 1000; // 5 segundos em produção, 1 minuto em dev

let pingInterval: NodeJS.Timeout | null = null;
let healthCheckInterval: NodeJS.Timeout | null = null;
let retryCount = 0;
let isConnected = true;

export const startKeepAlive = () => {
  if (pingInterval) {
    clearInterval(pingInterval);
  }
  if (healthCheckInterval) {
    clearInterval(healthCheckInterval);
  }

const ping = async () => {
  try {
      // Usando a tabela profiles que já existe no banco
      const { error } = await supabase.from('profiles').select('id').limit(1);
      if (error) throw error;
      
      retryCount = 0;
      isConnected = true;
      logger.debug('Ping successful', { context: 'keepAlive' });
  } catch (error) {
      retryCount++;
      isConnected = false;
      logger.error('Ping failed', { error, context: 'keepAlive' });
      
      if (retryCount >= MAX_RETRIES) {
        logger.error('Max retries reached, attempting reconnection', { context: 'keepAlive' });
        await reconnect();
    }
  }
};

const checkHealth = async () => {
    if (!isConnected) {
      logger.warn('Connection lost, attempting to reconnect', { context: 'keepAlive' });
      await reconnect();
    }
  };

  const reconnect = async () => {
    try {
      await supabase.auth.refreshSession();
      // Usando a tabela profiles que já existe no banco
      const { error } = await supabase.from('profiles').select('id').limit(1);
      if (error) throw error;
      
      isConnected = true;
      retryCount = 0;
      logger.info('Reconnection successful', { context: 'keepAlive' });
    } catch (error) {
      logger.error('Reconnection failed', { error, context: 'keepAlive' });
      setTimeout(reconnect, RETRY_DELAY);
    }
  };

  // Iniciar ping imediatamente
  ping();
  
  // Configurar intervalos
  pingInterval = setInterval(ping, PING_INTERVAL);
  healthCheckInterval = setInterval(checkHealth, HEALTH_CHECK_INTERVAL);
  
  // Limpar intervalos quando a página for fechada
  window.addEventListener('beforeunload', () => {
    if (pingInterval) clearInterval(pingInterval);
    if (healthCheckInterval) clearInterval(healthCheckInterval);
  });
};

export const stopKeepAlive = () => {
  if (pingInterval) {
    clearInterval(pingInterval);
    pingInterval = null;
    }
    if (healthCheckInterval) {
      clearInterval(healthCheckInterval);
      healthCheckInterval = null;
  }
}; 