import { QueryClient } from '@tanstack/react-query';
import { logger } from './logger';

interface MutationVariables {
  url: string;
  method?: string;
  headers?: HeadersInit;
  data?: unknown;
}

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // Dados ficam "frescos" por 5 segundos em produção
      staleTime: process.env.NODE_ENV === 'production' ? 5 * 1000 : 15 * 1000,
      // Cache por 30 segundos em produção
      gcTime: process.env.NODE_ENV === 'production' ? 30 * 1000 : 2 * 60 * 1000,
      // Retry em caso de falha
      retry: process.env.NODE_ENV === 'production' ? 3 : 1,
      // Refetch quando a janela ganha foco
      refetchOnWindowFocus: true,
      // Refetch quando reconecta à internet
      refetchOnReconnect: true,
      // Refetch quando a janela volta a ficar visível
      refetchOnMount: true,
      // Refetch interval em 10 segundos em produção
      refetchInterval: process.env.NODE_ENV === 'production' ? 10 * 1000 : false,
      // Refetch interval in background
      refetchIntervalInBackground: true,
      // Network mode
      networkMode: 'online',
      // Retry on mount
      retryOnMount: true,
      // Tempo máximo de retry com backoff exponencial
      retryDelay: (attemptIndex) => {
        const delay = Math.min(1000 * 2 ** attemptIndex, 30000);
        logger.info('Retry delay calculado', { attemptIndex, delay });
        return delay;
      },
      // Timeout de 30 segundos
      queryFn: async ({ queryKey }) => {
        const startTime = Date.now();
        logger.info('Iniciando query', { 
          queryKey,
          timestamp: new Date().toISOString(),
          environment: process.env.NODE_ENV
        });

        try {
          const controller = new AbortController();
          const timeoutId = setTimeout(() => controller.abort(), 30000);

          const response = await fetch(queryKey[0] as string, {
            signal: controller.signal,
          });

          clearTimeout(timeoutId);

          if (!response.ok) {
            const error = new Error(`HTTP error! status: ${response.status}`);
            logger.error('Erro na query - HTTP', { 
              error,
              queryKey,
              status: response.status,
              statusText: response.statusText,
              duration: Date.now() - startTime
            });
            throw error;
          }

          const data = await response.json();
          logger.info('Query concluída com sucesso', {
            queryKey,
            duration: Date.now() - startTime,
            dataSize: JSON.stringify(data).length
          });
          return data;
        } catch (error) {
          const duration = Date.now() - startTime;
          if (error instanceof Error && error.name === 'AbortError') {
            logger.error('Query timeout', {
              queryKey,
              duration,
              error: error.message
            });
          } else {
            logger.error('Erro na query', {
              error,
              queryKey,
              duration,
              errorType: error instanceof Error ? error.name : typeof error
            });
          }
          throw error;
        }
      },
    },
    mutations: {
      // Timeout de 30 segundos para mutations
      mutationFn: async (variables: MutationVariables) => {
        const { url, method = 'POST', headers = {}, data } = variables;
        const startTime = Date.now();
        
        logger.info('Iniciando mutation', { 
          url,
          method,
          timestamp: new Date().toISOString()
        });

        try {
          const controller = new AbortController();
          const timeoutId = setTimeout(() => controller.abort(), 30000);

          const response = await fetch(url, {
            method,
            headers: {
              'Content-Type': 'application/json',
              ...headers
            },
            body: data ? JSON.stringify(data) : undefined,
            signal: controller.signal
          });

          clearTimeout(timeoutId);

          if (!response.ok) {
            const error = new Error(`HTTP error! status: ${response.status}`);
            logger.error('Erro na mutation - HTTP', { 
              error,
              url,
              method,
              status: response.status,
              statusText: response.statusText,
              duration: Date.now() - startTime
            });
            throw error;
          }

          const responseData = await response.json();
          logger.info('Mutation concluída com sucesso', {
            url,
            method,
            duration: Date.now() - startTime
          });
          return responseData;
        } catch (error) {
          const duration = Date.now() - startTime;
          if (error instanceof Error && error.name === 'AbortError') {
            logger.error('Mutation timeout', {
              url,
              method,
              duration,
              error: error.message
            });
          } else {
            logger.error('Erro na mutation', {
              error,
              url,
              method,
              duration,
              errorType: error instanceof Error ? error.name : typeof error
            });
          }
          throw error;
        }
      },
    },
  },
}); 