import React, { useState, useEffect, useCallback } from 'react';
import { useProject } from '../../contexts/ProjectContext';
import { useAuth } from '../../contexts/SupabaseAuthContext';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { AlertTriangle, Clock, User, TrendingUp, Eye, Calendar, Plus, FolderOpen, Settings } from 'lucide-react';
import { Link } from 'react-router-dom';
import UserManagement from '../admin/UserManagement';
import { Database } from '@/integrations/supabase/types';
import { supabase } from '@/lib/supabase';
import { logger } from '@/lib/logger';
import { toast } from 'react-hot-toast';

type Task = Database['public']['Tables']['tasks']['Row'] & {
  tags?: string[];
  comments?: Database['public']['Tables']['comments']['Row'][];
  projectName?: string;
  projects?: {
    name: string;
  };
};

const AdminDashboard = () => {
  const { projects, getOverdueTasks, getUpcomingTasks } = useProject();
  const { user, hasPermission } = useAuth();
  const [activeTab, setActiveTab] = useState<'dashboard' | 'users'>('dashboard');
  const [overdueTasks, setOverdueTasks] = useState<Task[]>([]);
  const [upcomingTasks, setUpcomingTasks] = useState<Task[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadDashboardData = useCallback(async () => {
    if (!user) return;
    
    try {
      setIsLoading(true);
      setError(null);
      
      logger.debug('[AdminDashboard] Iniciando carregamento de dados...');
      
      const [overdueTasksData, upcomingTasksData] = await Promise.all([
        getOverdueTasks(),
        getUpcomingTasks(7)
      ]);

      setOverdueTasks(overdueTasksData);
      setUpcomingTasks(upcomingTasksData);
      
      logger.debug('[AdminDashboard] Dados carregados com sucesso', {
        overdueTasks: overdueTasksData.length,
        upcomingTasks: upcomingTasksData.length
      });
    } catch (error) {
      logger.error('[AdminDashboard] Erro ao carregar dados', { error });
      setError('Erro ao carregar dados do dashboard');
      toast.error('Erro ao carregar dados do dashboard');
    } finally {
      setIsLoading(false);
    }
  }, [user, getOverdueTasks, getUpcomingTasks]);

  useEffect(() => {
    loadDashboardData();
  }, [loadDashboardData]);

  // Configurar assinaturas em tempo real
  useEffect(() => {
    if (!user) return;

    logger.debug('[AdminDashboard] Configurando assinaturas em tempo real...');

    let retryCount = 0;
    const maxRetries = 5;
    const retryDelay = 5000;
    let subscription: ReturnType<typeof supabase.channel> | null = null;
    let retryTimeout: NodeJS.Timeout | null = null;
    let isComponentMounted = true;

    const setupSubscription = async () => {
      try {
        // Limpar assinatura anterior se existir
        if (subscription) {
          try {
            await subscription.unsubscribe();
          } catch (error) {
            logger.error('[AdminDashboard] Erro ao limpar assinatura anterior:', error);
          }
        }

        // Limpar timeout anterior se existir
        if (retryTimeout) {
          clearTimeout(retryTimeout);
        }

        // Criar nova assinatura
        subscription = supabase
          .channel('admin_dashboard_tasks')
          .on(
            'postgres_changes',
            {
              event: '*',
              schema: 'public',
              table: 'tasks'
            },
            async (payload) => {
              if (!isComponentMounted) return;
              
              logger.debug('[AdminDashboard] Mudança detectada em tarefas:', payload);
              try {
                await loadDashboardData();
                logger.debug('[AdminDashboard] Dados atualizados com sucesso');
              } catch (error) {
                logger.error('[AdminDashboard] Erro ao atualizar dados:', error);
              }
            }
          )
          .subscribe(async (status) => {
            if (!isComponentMounted) return;

            logger.debug('[AdminDashboard] Status da assinatura:', status);
            
            if (status === 'SUBSCRIBED') {
              retryCount = 0;
              logger.debug('[AdminDashboard] Assinatura estabelecida com sucesso');
            } else if (status === 'CHANNEL_ERROR' || status === 'CLOSED') {
              logger.error('[AdminDashboard] Erro na assinatura', { status, retryCount });
              
              if (retryCount < maxRetries && isComponentMounted) {
                retryCount++;
                logger.debug(`[AdminDashboard] Tentativa ${retryCount} de reconexão em ${retryDelay}ms`);
                
                retryTimeout = setTimeout(async () => {
                  if (isComponentMounted) {
                    await setupSubscription();
                  }
                }, retryDelay);
              } else {
                logger.error('[AdminDashboard] Máximo de tentativas de reconexão atingido');
                toast.error('Não foi possível estabelecer conexão em tempo real. Algumas atualizações podem não ser refletidas imediatamente.');
              }
            }
          });

        return subscription;
      } catch (error) {
        logger.error('[AdminDashboard] Erro ao configurar assinatura:', error);
        throw error;
      }
    };

    // Iniciar assinatura
    setupSubscription().catch(error => {
      logger.error('[AdminDashboard] Erro ao iniciar assinatura:', error);
    });

    // Cleanup
    return () => {
      isComponentMounted = false;
      logger.debug('[AdminDashboard] Limpando assinaturas...');
      
      if (retryTimeout) {
        clearTimeout(retryTimeout);
      }
      
      if (subscription) {
        subscription.unsubscribe().catch(error => {
          logger.error('[AdminDashboard] Erro ao limpar assinatura:', error);
        });
      }
    };
  }, [user, loadDashboardData]);

  if (!user || !hasPermission('view_analytics')) {
    return null;
  }

  const totalTasks = projects.reduce((acc, project) => acc + (project.tasks?.length || 0), 0);
  const completedTasks = projects.reduce((acc, project) => 
    acc + (project.tasks?.filter(task => task.status === 'done').length || 0), 0);
  const taskProgress = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;

  const projectsWithIssues = projects.filter(project => {
    const projectOverdueTasks = (project.tasks || []).filter(task => 
      task.due_date && new Date(task.due_date) < new Date() && task.status !== 'done'
    ).length;
    return projectOverdueTasks > 0;
  });

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return 'border-l-red-500 bg-red-500/10';
      case 'medium': return 'border-l-yellow-500 bg-yellow-500/10';
      case 'low': return 'border-l-green-500 bg-green-500/10';
      default: return 'border-l-gray-500 bg-gray-500/10';
    }
  };

  const getTaskStatus = (status: string) => {
    switch (status) {
      case 'done':
        return { label: 'Concluída', variant: 'default' as const };
      case 'doing':
        return { label: 'Em Progresso', variant: 'secondary' as const };
      default:
        return { label: 'Pendente', variant: 'outline' as const };
    }
  };

  if (activeTab === 'users') {
    return <UserManagement />;
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="space-y-1">
          <h1 className="text-3xl font-bold text-foreground">Dashboard Administrativo</h1>
          <p className="text-muted-foreground">Visão geral completa de todos os projetos e prazos críticos</p>
        </div>
        <div className="flex gap-3">
          {/* Apenas mostrar botão de usuários para admins */}
          {user.role === 'admin' && (
            <Button
              variant="outline"
              onClick={() => setActiveTab('users')}
              className="flex items-center space-x-2"
            >
              <Settings className="h-4 w-4" />
              <span>Usuários</span>
            </Button>
          )}
          <Button asChild className="gradient-primary hover:opacity-90">
            <Link to="/projects">
              <Plus className="mr-2 h-4 w-4" />
              Novo Projeto
            </Link>
          </Button>
          <Button asChild variant="outline" className="border-border hover:bg-accent">
            <Link to="/calendar">
              <Calendar className="mr-2 h-4 w-4" />
              Calendário
            </Link>
          </Button>
        </div>
      </div>

      {/* Critical Alerts */}
      {overdueTasks.length > 0 && (
        <Alert className="border-red-500/50 bg-red-500/10 animate-fade-in">
          <AlertTriangle className="h-4 w-4 text-red-500" />
          <AlertDescription className="text-red-400">
            <strong>{overdueTasks.length} tarefas atrasadas</strong> precisam de atenção imediata!
          </AlertDescription>
        </Alert>
      )}

      {/* Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="card-dark animate-fade-in">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-card-foreground">Projetos Ativos</CardTitle>
            <FolderOpen className="h-5 w-5 text-primary" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-foreground">{projects.length}</div>
            <p className="text-xs text-muted-foreground">
              {projectsWithIssues.length} com problemas
            </p>
            <div className="mt-2 flex items-center space-x-2">
              <div className="flex-1 h-2 bg-muted rounded-full overflow-hidden">
                <div 
                  className="h-full bg-primary transition-all duration-300" 
                  style={{ width: `${projects.length > 0 ? 100 : 0}%` }}
                />
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className={`card-dark animate-fade-in ${overdueTasks.length > 0 ? 'border-l-4 border-l-red-500' : ''}`} style={{ animationDelay: '0.1s' }}>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-card-foreground">Tarefas Atrasadas</CardTitle>
            <AlertTriangle className="h-5 w-5 text-red-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-red-500">{overdueTasks.length}</div>
            <p className="text-xs text-muted-foreground">
              Requerem ação imediata
            </p>
            {overdueTasks.length > 0 && (
              <div className="mt-2">
                <Button size="sm" variant="destructive" className="text-xs" asChild>
                  <Link to="/tasks?filter=overdue">
                    Ver Tarefas
                  </Link>
                </Button>
              </div>
            )}
          </CardContent>
        </Card>

        <Card className={`card-dark animate-fade-in ${upcomingTasks.length > 0 ? 'border-l-4 border-l-yellow-500' : ''}`} style={{ animationDelay: '0.2s' }}>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-card-foreground">Próximos Prazos</CardTitle>
            <Clock className="h-5 w-5 text-yellow-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-yellow-500">{upcomingTasks.length}</div>
            <p className="text-xs text-muted-foreground">
              Próximos 7 dias
            </p>
            <div className="mt-2 flex items-center space-x-2">
              <Calendar className="h-3 w-3 text-yellow-500" />
              <span className="text-xs text-muted-foreground">Monitorar</span>
            </div>
          </CardContent>
        </Card>

        <Card className="card-dark animate-fade-in" style={{ animationDelay: '0.3s' }}>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-card-foreground">Progresso Geral</CardTitle>
            <TrendingUp className="h-5 w-5 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-foreground">{Math.round(taskProgress)}%</div>
            <div className="mt-2 h-2 bg-muted rounded-full overflow-hidden">
              <div 
                className="h-full gradient-success transition-all duration-500" 
                style={{ width: `${taskProgress}%` }}
              />
            </div>
            <p className="text-xs text-muted-foreground mt-2">
              {completedTasks} de {totalTasks} tarefas
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Critical Tasks Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card className="card-dark">
          <CardHeader>
            <CardTitle className="flex items-center text-red-400">
              <AlertTriangle className="mr-2 h-5 w-5" />
              Tarefas Atrasadas
            </CardTitle>
            <CardDescription>Tarefas que já passaram do prazo</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-3 max-h-96 overflow-y-auto">
              {overdueTasks.slice(0, 6).map((task, index) => {
                const status = getTaskStatus(task.status);
                return (
                  <div 
                    key={task.id} 
                    className={`p-3 rounded-lg border-l-4 border-l-red-500 bg-red-500/5 hover:bg-red-500/10 transition-colors animate-slide-up`}
                    style={{ animationDelay: `${index * 0.1}s` }}
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-foreground truncate">{task.title}</p>
                        <p className="text-xs text-muted-foreground truncate">{task.projectName}</p>
                        <div className="flex items-center space-x-2 mt-1">
                          <Badge variant={status.variant} className="text-xs">
                            {status.label}
                          </Badge>
                          <span className="text-xs text-red-400">
                            Venceu: {new Date(task.due_date!).toLocaleDateString('pt-BR')}
                          </span>
                        </div>
                      </div>
                      {task.assigned_to && (
                        <div className="flex items-center ml-2">
                          <User className="h-3 w-3 text-muted-foreground mr-1" />
                          <span className="text-xs text-muted-foreground">{task.assigned_to || 'Não atribuído'}</span>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
              {overdueTasks.length === 0 && (
                <div className="text-center py-8 text-muted-foreground">
                  <AlertTriangle className="h-8 w-8 mx-auto mb-2 text-green-500" />
                  <p className="text-sm">Nenhuma tarefa atrasada! 🎉</p>
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Upcoming Tasks */}
        <Card className="card-dark">
          <CardHeader>
            <CardTitle className="flex items-center text-yellow-400">
              <Clock className="mr-2 h-5 w-5" />
              Próximos Prazos
            </CardTitle>
            <CardDescription>Tarefas que vencem nos próximos 7 dias</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-3 max-h-96 overflow-y-auto">
              {upcomingTasks.slice(0, 6).map((task, index) => {
                const status = getTaskStatus(task.status);
                return (
                  <div 
                    key={task.id} 
                    className={`p-3 rounded-lg border-l-4 border-l-yellow-500 bg-yellow-500/5 hover:bg-yellow-500/10 transition-colors animate-slide-up`}
                    style={{ animationDelay: `${index * 0.1}s` }}
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-foreground truncate">{task.title}</p>
                        <p className="text-xs text-muted-foreground truncate">
                          {task.projectName || task.projects?.name || 'Projeto não encontrado'}
                        </p>
                        <div className="flex items-center space-x-2 mt-1">
                          <Badge variant={status.variant} className="text-xs">
                            {status.label}
                          </Badge>
                          <span className="text-xs text-yellow-400">
                            Vence: {new Date(task.due_date!).toLocaleDateString('pt-BR')}
                          </span>
                        </div>
                      </div>
                      {task.assigned_to && (
                        <div className="flex items-center ml-2">
                          <User className="h-3 w-3 text-muted-foreground mr-1" />
                          <span className="text-xs text-muted-foreground">{task.assigned_to || 'Não atribuído'}</span>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
              {upcomingTasks.length === 0 && (
                <div className="text-center py-8 text-muted-foreground">
                  <Clock className="h-8 w-8 mx-auto mb-2 text-green-500" />
                  <p className="text-sm">Nenhum prazo próximo!</p>
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Projects with Issues */}
      <Card className="card-dark">
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-foreground">Projetos que Precisam de Atenção</CardTitle>
              <CardDescription>Projetos com tarefas atrasadas ou próximas do prazo</CardDescription>
            </div>
            <Button variant="outline" size="sm" asChild>
              <Link to="/projects">
                <Eye className="mr-2 h-4 w-4" />
                Ver Todos
              </Link>
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {projectsWithIssues.slice(0, 5).map((project, index) => {
              const projectOverdueTasks = (project.tasks || []).filter(task => 
                task.due_date && new Date(task.due_date) < new Date() && task.status !== 'done'
              ).length;
              const projectUpcomingTasks = (project.tasks || []).filter(task => {
                if (!task.due_date || task.status === 'done') return false;
                const dueDate = new Date(task.due_date);
                const today = new Date();
                const futureDate = new Date();
                futureDate.setDate(today.getDate() + 7);
                return dueDate >= today && dueDate <= futureDate;
              }).length;
              
              const completedTasks = (project.tasks || []).filter(t => t.status === 'done').length;
              const progress = (project.tasks || []).length > 0 ? (completedTasks / (project.tasks || []).length) * 100 : 0;

              return (
                <div 
                  key={project.id}
                  className={`p-4 rounded-lg border-l-4 border-l-gray-500 hover:bg-accent/5 transition-colors animate-slide-up`}
                  style={{ animationDelay: `${index * 0.1}s` }}
                >
                  <div className="flex items-center space-x-4 flex-1">
                    <div className="flex-1 min-w-0">
                      <h4 className="text-sm font-medium text-foreground truncate">{project.name}</h4>
                      <div className="flex items-center space-x-4 text-xs text-muted-foreground mt-1">
                        <span>{(project.tasks || []).length} tarefas</span>
                        {projectOverdueTasks > 0 && (
                          <span className="text-red-400">{projectOverdueTasks} atrasadas</span>
                        )}
                        {projectUpcomingTasks > 0 && (
                          <span className="text-yellow-400">{projectUpcomingTasks} próximas</span>
                        )}
                      </div>
                      <div className="mt-2">
                        <Progress value={progress} className="h-2" />
                      </div>
                    </div>
                  </div>
                  <div className="flex space-x-2">
                    <Button variant="outline" size="sm" asChild>
                      <Link to={`/projects/${project.id}`}>Ver Detalhes</Link>
                    </Button>
                    <Button size="sm" className="gradient-primary" asChild>
                      <Link to={`/projects/${project.id}/kanban`}>Kanban</Link>
                    </Button>
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default AdminDashboard;
