import { usePageVisibility } from '@/hooks/usePageVisibility';
import { useAuth } from '@/contexts/SupabaseAuthContext';
import { useQueryClient } from '@tanstack/react-query';
import { useState, useEffect, useRef } from 'react';
import { logger } from '@/lib/logger';
import { toast } from 'sonner';

export function PageVisibilityHandler() {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [lastRefresh, setLastRefresh] = useState<Date | null>(null);
  const isMountedRef = useRef(true);
  const refreshTimeoutRef = useRef<NodeJS.Timeout>();

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
      if (refreshTimeoutRef.current) {
        clearTimeout(refreshTimeoutRef.current);
      }
    };
  }, []);

  const handleDiscreteRefresh = async () => {
    if (!user || isRefreshing) return;
    
    const startTime = Date.now();
    setIsRefreshing(true);
    
    try {
      logger.debug('Iniciando refresh discreto', { 
        context: 'PageVisibilityHandler',
        timestamp: new Date().toISOString(),
        user: user.id
      });
      
      // Limpa todo o cache antes de recarregar
      queryClient.clear();
      
      // Invalida todas as queries ativas
      await queryClient.invalidateQueries();
      
      // Força o refetch das queries mais importantes
      await Promise.all([
        queryClient.refetchQueries({ queryKey: ['user'] }),
        queryClient.refetchQueries({ queryKey: ['profile'] }),
        queryClient.refetchQueries({ queryKey: ['projects'] }),
        queryClient.refetchQueries({ queryKey: ['tasks'] }),
        queryClient.refetchQueries({ queryKey: ['dashboard'] })
      ]);
      
      // Dispara evento de refresh
      window.dispatchEvent(new CustomEvent('app-refresh'));
      
      const duration = Date.now() - startTime;
      setLastRefresh(new Date());
      
      logger.info('Refresh discreto concluído', { 
        context: 'PageVisibilityHandler',
        duration,
        timestamp: new Date().toISOString(),
        user: user.id
      });

      // Mostra toast apenas se o refresh demorou mais que 500ms
      if (duration > 500) {
        toast.info('Dados atualizados', {
          description: `Última atualização: ${new Date().toLocaleTimeString()}`,
          duration: 2000,
        });
      }
    } catch (error) {
      logger.error('Erro no refresh discreto', { 
        error, 
        context: 'PageVisibilityHandler',
        timestamp: new Date().toISOString(),
        user: user?.id
      });
      
      toast.error('Erro ao atualizar dados', {
        description: 'Tente recarregar a página manualmente',
        duration: 3000,
      });
    } finally {
      if (isMountedRef.current) {
        setIsRefreshing(false);
      }
    }
  };

  useEffect(() => {
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        // Se o usuário ficou mais de 5 minutos fora, força um refresh completo
        const now = new Date();
        const timeSinceLastRefresh = lastRefresh 
          ? now.getTime() - lastRefresh.getTime() 
          : Infinity;
        
        if (timeSinceLastRefresh > 5 * 60 * 1000) {
          logger.info('Detectado retorno após inatividade prolongada', {
            timeSinceLastRefresh,
            lastRefresh
          });
          handleDiscreteRefresh();
        } else {
          // Caso contrário, apenas invalida as queries
          queryClient.invalidateQueries();
        }
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [lastRefresh]);

  return null;
} 